def compute(vars):
    provisions = vars["v1"]
    total_deferred_tax_assets = vars["v2"]

    if total_deferred_tax_assets == 0:
        return None

    value = provisions / total_deferred_tax_assets * 100

    return {
        "value": value,
        "trace": {
            "provisions": provisions,
            "total_deferred_tax_assets": total_deferred_tax_assets,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
